DO $fix$ DECLARE source text; BEGIN SELECT pg_get_functiondef('trip_private.culture_quest(text,uuid,uuid,text,uuid,integer,integer)'::regprocedure) INTO source; source:=replace(source,'IF s.position>=total THEN UPDATE','IF s.position>=total THEN SELECT * INTO c FROM public.cultural_inspirations WHERE id=s.card_id; UPDATE'); source:=replace(source,'SELECT count(*) INTO answer_count FROM public.culture_quest_answers','SELECT count(*) INTO total FROM public.culture_quest_items WHERE card_id=s.card_id; SELECT count(*) INTO answer_count FROM public.culture_quest_answers'); source:=replace(source,'''session'',s.id,','''session'',s.id,''card'',s.card_id,'); EXECUTE source; END $fix$;